import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"1.1 明确首个场景与真实任务","description":"确定首位用户、15 个真实任务、非目标和验收标准。","frontmatter":{"title":"1.1 明确首个场景与真实任务","description":"确定首位用户、15 个真实任务、非目标和验收标准。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-1/1-1.md","filePath":"delivery/stage-1/1-1.md","lastUpdated":1794302657000}'),i={name:"delivery/stage-1/1-1.md"};function o(h,e,n,s,d,c){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="_1-1-明确首个场景与真实任务" tabindex="-1">1.1 明确首个场景与真实任务 <a class="header-anchor" href="#_1-1-明确首个场景与真实任务" aria-label="Permalink to &quot;1.1 明确首个场景与真实任务&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已完成：</strong> 15 个跨行业任务写入独立仓库 <a href="https://github.com/hearthproject/hearth-eval" target="_blank" rel="noreferrer">hearth-eval</a> 的 <code>eval/</code> 目录，覆盖文档、网页、研发、数据/财务、客户支持、人事、教育、营销等任务族；验收口径固定为至少 10/15 通过。</li><li><strong>实际结果：</strong> 15 个任务全部运行，13 个通过。T07 和 T08 保留为未完成边界，不影响硬门槛。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>确定 Hearth 首先为谁解决什么问题，并把工作整理成 15 个跨行业、可直接执行的真实任务。阶段结束时，团队应当能说清楚首位用户、首批 15 个任务、明确不做什么，以及至少 10 个通过算完成。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>找到一位愿意提供真实任务和反馈的首位用户，记录他每天重复做、最希望交给系统的工作。</li><li>以 <a href="https://github.com/hearthproject/hearth-eval" target="_blank" rel="noreferrer">hearth-eval</a> 的 <code>eval/</code> 目录中 15 个具体任务为基线；如果真实使用中出现更好的任务，可以补充候选，但 MVP 固定验收这 15 项。</li><li>不要求只选一个任务族；15 项应覆盖文档处理、网页资料、研发协作、数据/财务、客户支持、人事、教育和营销等多个领域。</li><li>写出一句话定位和“暂不做什么”清单，避免第一阶段被新想法带偏。</li><li>记录这些任务现在怎么做、花多少时间、哪里容易出错，作为后续对比。</li><li>确定 MVP 的验收方式：15 个任务中至少 10 个通过验收，失败任务能说明原因并恢复。</li></ol>',7)])])}const u=a(i,[["render",o]]);export{p as __pageData,u as default};
